import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Copy, Sparkles, ShieldCheck, CheckCircle2, AlertTriangle, Terminal, BookOpen, Mail, FileText } from 'lucide-react';
import toast from 'react-hot-toast';
import ScoreCard from '../components/ScoreCard';
import SkillBadge from '../components/SkillBadge';
import RewriteCard from '../components/RewriteCard';
import RoadmapItem from '../components/RoadmapItem';
import CoverLetterCard from '../components/CoverLetterCard';
import BackgroundEffects from '../components/BackgroundEffects';
import { mergeProfile } from '../utils/profileMerger';

const Results = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [result, setResult] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const storedResult = sessionStorage.getItem('analysisResult');
    if (storedResult) {
      setResult(JSON.parse(storedResult));
    } else {
      navigate('/');
    }
  }, [navigate]);

  if (!result) {
    return null;
  }

  const coreMatch = result?.core_match || {
    overall_score: 0,
    section_scores: {},
    matched_skills: [],
    missing_skills: [],
    improvement_tips: [],
    keyword_gaps: [],
    summary: 'No analysis available'
  };

  const ats = result?.ats || {
    ats_score: 0,
    parsing_issues: [],
    detected_sections: [],
    missing_sections: [],
    keyword_density: {},
    formatting_warnings: [],
    ats_verdict: 'No ATS analysis available'
  };

  const gaps = result?.gaps || {
    readiness_percentage: 0,
    gap_summary: 'No gap analysis available',
    skill_gaps: [],
    milestones: []
  };

  const rewrites = result?.rewrites || {
    rewrites: []
  };

  const coverLetter = result?.cover_letter || {
    subject_line: '',
    cover_letter: '',
    highlights_used: [],
    tone: ''
  };

  // Generate Unified Profile view via profileMerger
  const unifiedProfile = mergeProfile(result, {
    skills: ["React", "Node.js", "Express", "PostgreSQL", "Docker", "Git"],
    username: "candidate-dev"
  });

  const tabs = [
    { id: 'overview', label: 'Overview', icon: Sparkles },
    { id: 'unified', label: 'Unified Profile & Verification', icon: ShieldCheck },
    { id: 'ats', label: 'ATS Inspection', icon: CheckCircle2 },
    { id: 'rewrites', label: 'AI Bullet Rewrites', icon: FileText },
    { id: 'roadmap', label: 'Gap Roadmap', icon: BookOpen },
    { id: 'coverletter', label: 'Cover Letter', icon: Mail },
  ];

  const handleCopyAllRewrites = () => {
    const allRewrites = rewrites.rewrites
      .map(r => r.improved)
      .join('\n');
    navigator.clipboard.writeText(allRewrites);
    toast.success('All improved bullet rewrites copied to clipboard!');
  };

  const renderOverview = () => (
    <div className="space-y-8 animate-fade-in">

      {/* Overall Score Meter */}
      <div className="glass-card p-8 rounded-3xl border border-scifi-600/30 text-center relative overflow-hidden shadow-purple-glow">
        <h2 className="text-xl font-heading font-bold text-scifi-200 mb-6 flex items-center justify-center space-x-2">
          <Sparkles className="w-5 h-5 text-scifi-200" />
          <span>Overall Match & Verification Score</span>
        </h2>

        <div className="w-56 h-56 mx-auto relative flex items-center justify-center">
          <svg className="w-full h-full transform -rotate-90">
            <circle
              cx="112"
              cy="112"
              r="96"
              stroke="rgba(99, 89, 133, 0.2)"
              strokeWidth="14"
              fill="none"
            />
            <circle
              cx="112"
              cy="112"
              r="96"
              stroke="#635985"
              strokeWidth="14"
              fill="none"
              strokeDasharray={`${2 * Math.PI * 96}`}
              strokeDashoffset={`${2 * Math.PI * 96 * (1 - ((coreMatch?.overall_score || 0) / 100))}`}
              strokeLinecap="round"
              className="transition-all duration-1000 ease-out shadow-purple-glow"
            />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-6xl font-heading font-extrabold text-scifi-100 tracking-tight glow-text-purple">
              {Math.round(coreMatch?.overall_score || 0)}%
            </span>
            <span className="text-xs font-mono text-scifi-200 uppercase tracking-widest mt-1">
              MATCH RATING
            </span>
          </div>
        </div>
      </div>

      {/* Section Scores Grid */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <ScoreCard title="Skills Match" score={coreMatch?.section_scores?.skills || 0} />
        <ScoreCard title="Experience Match" score={coreMatch?.section_scores?.experience || 0} />
        <ScoreCard title="Education Score" score={coreMatch?.section_scores?.education || 0} />
        <ScoreCard title="Keywords Alignment" score={coreMatch?.section_scores?.keywords || 0} />
      </div>

      {/* Executive Summary */}
      <div className="glass-card p-6 sm:p-8 rounded-3xl border border-scifi-600/30">
        <h3 className="text-lg font-heading font-bold text-scifi-100 mb-3 flex items-center space-x-2">
          <Terminal className="w-5 h-5 text-scifi-200" />
          <span>AI Evaluation Summary</span>
        </h3>
        <p className="text-scifi-200 font-sans leading-relaxed text-sm sm:text-base">
          {coreMatch?.summary || "No summary available."}
        </p>
      </div>

      {/* Matched & Missing Skills Grid */}
      <div className="grid md:grid-cols-2 gap-6">
        <div className="glass-card p-6 rounded-3xl border border-scifi-600/40 shadow-purple-glow">
          <h3 className="text-base font-heading font-bold mb-4 text-scifi-100 flex items-center space-x-2">
            <CheckCircle2 className="w-5 h-5 text-scifi-200" />
            <span>Matched Resume Skills ({coreMatch?.matched_skills?.length || 0})</span>
          </h3>
          <div className="flex flex-wrap gap-2">
            {coreMatch?.matched_skills?.map((skill, index) => (
              <SkillBadge key={index} skill={skill} type="matched" />
            ))}
          </div>
        </div>

        <div className="glass-card p-6 rounded-3xl border border-scifi-600/30">
          <h3 className="text-base font-heading font-bold mb-4 text-scifi-200 flex items-center space-x-2">
            <AlertTriangle className="w-5 h-5 text-scifi-400" />
            <span>Missing Target Skills ({coreMatch?.missing_skills?.length || 0})</span>
          </h3>
          <div className="flex flex-wrap gap-2">
            {coreMatch?.missing_skills?.map((skill, index) => (
              <SkillBadge key={index} skill={skill} type="missing" />
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  const renderUnified = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="glass-card p-6 sm:p-8 rounded-3xl border border-scifi-600/30">

        {/* Header */}
        <div className="flex items-center space-x-3 mb-6 pb-4 border-b border-scifi-600/20">
          <ShieldCheck className="w-6 h-6 text-scifi-200" />
          <div>
            <h2 className="text-xl font-heading font-bold text-scifi-100">Unified Profile Layer (Person B)</h2>
            <p className="text-xs font-mono text-scifi-200">
              Aggregated resume analysis & GitHub code evidence
            </p>
          </div>
        </div>

        {/* Verified Skills */}
        <div className="mb-6">
          <h3 className="text-sm font-mono uppercase text-scifi-100 font-bold mb-3 flex items-center space-x-2">
            <CheckCircle2 className="w-4 h-4 text-scifi-200" />
            <span>Verified Skills (Code Evidence Verified on GitHub)</span>
          </h3>
          <div className="flex flex-wrap gap-2">
            {unifiedProfile.verifiedSkills.length > 0 ? (
              unifiedProfile.verifiedSkills.map((v, i) => (
                <SkillBadge key={i} skill={v.skill} type="verified" evidence={v.evidence} />
              ))
            ) : (
              <p className="text-xs font-mono text-scifi-200">No verified code claims found.</p>
            )}
          </div>
        </div>

        {/* Unverified Resume Claims */}
        <div className="mb-6">
          <h3 className="text-sm font-mono uppercase text-scifi-200 font-bold mb-3 flex items-center space-x-2">
            <AlertTriangle className="w-4 h-4 text-scifi-400" />
            <span>Unverified Resume Claims (Lacking GitHub Repos)</span>
          </h3>
          <div className="flex flex-wrap gap-2">
            {unifiedProfile.unverifiedClaims.map((claim, i) => (
              <span key={i} className="px-3 py-1 rounded-full text-xs font-mono bg-scifi-800 text-scifi-200 border border-scifi-600/30">
                ⚠️ {claim}
              </span>
            ))}
          </div>
        </div>

        {/* Resume Recommendations */}
        <div>
          <h3 className="text-sm font-mono uppercase text-scifi-100 font-bold mb-3 flex items-center space-x-2">
            <Sparkles className="w-4 h-4 text-scifi-200" />
            <span>Resume Recommendations (GitHub Skills Missing on Resume)</span>
          </h3>
          <ul className="space-y-2">
            {unifiedProfile.resumeRecommendations.map((rec, i) => (
              <li key={i} className="p-3 rounded-xl bg-scifi-950/80 border border-scifi-600/20 text-xs font-mono text-scifi-100 flex items-center space-x-2">
                <span className="text-scifi-200">→</span>
                <span>{rec}</span>
              </li>
            ))}
          </ul>
        </div>

      </div>
    </div>
  );

  const renderATS = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="glass-card p-6 sm:p-8 rounded-3xl border border-scifi-600/30">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <div>
            <h2 className="text-2xl font-heading font-bold text-scifi-100">ATS Compatibility Audit</h2>
            <p className="text-xs font-mono text-scifi-200">Automated Screening Filter Simulation</p>
          </div>

          <span className={`px-4 py-2 rounded-full font-mono text-xs font-bold border shrink-0 ${
            ats.ats_verdict?.includes('Pass') ? 'bg-scifi-600/30 text-scifi-100 border-scifi-600/50 shadow-purple-glow' :
            'bg-scifi-800/80 text-scifi-200 border-scifi-600/30'
          }`}>
            {ats.ats_verdict}
          </span>
        </div>

        {/* ATS Progress Bar */}
        <div className="space-y-2 mb-8">
          <div className="w-full h-4 bg-scifi-950 rounded-full p-0.5 border border-scifi-600/30 overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-scifi-800 to-scifi-500 rounded-full transition-all duration-700 shadow-purple-glow"
              style={{ width: `${ats.ats_score}%` }}
            />
          </div>
          <div className="flex justify-between text-xs font-mono text-scifi-200">
            <span>ATS Compatibility Index</span>
            <span className="text-scifi-100 font-bold">{Math.round(ats.ats_score)}%</span>
          </div>
        </div>

        {/* Section Checks Grid */}
        <div className="grid md:grid-cols-2 gap-6">
          <div className="p-5 rounded-2xl bg-scifi-950/80 border border-scifi-600/20">
            <h3 className="font-heading font-bold text-scifi-100 text-base mb-3">Detected Resume Sections</h3>
            <ul className="space-y-2">
              {ats.detected_sections?.map((sec, i) => (
                <li key={i} className="flex items-center text-xs font-mono text-scifi-100">
                  <span className="w-2 h-2 rounded-full bg-scifi-200 mr-2 shadow-purple-glow" />
                  {sec}
                </li>
              ))}
            </ul>
          </div>

          {ats.missing_sections?.length > 0 && (
            <div className="p-5 rounded-2xl bg-scifi-950/80 border border-scifi-600/30">
              <h3 className="font-heading font-bold text-scifi-200 text-base mb-3">Missing Resume Sections</h3>
              <ul className="space-y-2">
                {ats.missing_sections.map((sec, i) => (
                  <li key={i} className="flex items-center text-xs font-mono text-scifi-200">
                    <span className="mr-2">⚠️</span>
                    {sec}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>

        {/* Keyword Density Table */}
        <div className="mt-8 pt-6 border-t border-scifi-600/20">
          <h3 className="font-heading font-bold text-scifi-100 text-base mb-4">ATS Keyword Density Matrix</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs font-mono">
              <thead>
                <tr className="border-b border-scifi-600/20 text-scifi-200">
                  <th className="pb-3">High Match Keywords</th>
                  <th className="pb-3">Partial Match</th>
                  <th className="pb-3">Missing Keywords</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-scifi-600/10">
                <tr>
                  <td className="py-3 pr-2">
                    <div className="flex flex-wrap gap-1">
                      {ats.keyword_density?.high_match?.map((kw, i) => (
                        <span key={i} className="px-2 py-0.5 rounded bg-scifi-600/30 text-scifi-100 border border-scifi-600/40">
                          {kw}
                        </span>
                      ))}
                    </div>
                  </td>
                  <td className="py-3 pr-2">
                    <div className="flex flex-wrap gap-1">
                      {ats.keyword_density?.partial_match?.map((kw, i) => (
                        <span key={i} className="px-2 py-0.5 rounded bg-scifi-700 text-scifi-100 border border-scifi-600/30">
                          {kw}
                        </span>
                      ))}
                    </div>
                  </td>
                  <td className="py-3">
                    <div className="flex flex-wrap gap-1">
                      {ats.keyword_density?.missing?.map((kw, i) => (
                        <span key={i} className="px-2 py-0.5 rounded bg-scifi-800 text-scifi-200 border border-scifi-600/30">
                          {kw}
                        </span>
                      ))}
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );

  const renderRewrites = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-xl font-heading font-bold text-scifi-100">AI-Optimized Bullet Rewrites</h2>
          <p className="text-xs font-mono text-scifi-200">Action-oriented impact bullet points</p>
        </div>

        <button
          onClick={handleCopyAllRewrites}
          className="flex items-center space-x-2 px-4 py-2.5 rounded-xl bg-scifi-600/30 hover:bg-scifi-600/50 text-scifi-100 border border-scifi-600/50 font-mono text-xs shadow-purple-glow transition-all"
        >
          <Copy className="w-4 h-4" />
          <span>Copy All Rewrites</span>
        </button>
      </div>

      <div className="space-y-4">
        {rewrites.rewrites?.map((rewrite, index) => (
          <RewriteCard key={index} rewrite={rewrite} />
        ))}
      </div>
    </div>
  );

  const renderRoadmap = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="glass-card p-6 sm:p-8 rounded-3xl border border-scifi-600/30 text-center">
        <h2 className="text-xl font-heading font-bold text-scifi-100 mb-2">Job Readiness Index</h2>
        <div className="text-6xl font-heading font-extrabold text-scifi-100 mb-2 glow-text-purple">
          {Math.round(gaps.readiness_percentage)}%
        </div>
        <p className="text-sm text-scifi-200 max-w-xl mx-auto">{gaps.gap_summary}</p>
      </div>

      {/* Milestones Progress */}
      <div className="glass-card p-6 sm:p-8 rounded-3xl border border-scifi-600/30">
        <h3 className="font-heading font-bold text-scifi-100 text-lg mb-4">Upskilling Milestones</h3>
        <div className="space-y-4">
          {gaps.milestones?.map((milestone, index) => (
            <div key={index}>
              <div className="flex justify-between text-xs font-mono text-scifi-200 mb-1">
                <span>{milestone.label}</span>
                <span className="text-scifi-100 font-bold">{milestone.percentage}%</span>
              </div>
              <div className="w-full h-2.5 bg-scifi-950 rounded-full overflow-hidden border border-scifi-600/20">
                <div
                  className="h-full bg-gradient-to-r from-scifi-800 to-scifi-500 rounded-full transition-all duration-500"
                  style={{ width: `${milestone.percentage}%` }}
                />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Skill Gaps List */}
      <div>
        <h3 className="font-heading font-bold text-scifi-100 text-lg mb-4">Skill Gap Analysis & Resources</h3>
        {gaps.skill_gaps?.map((gap, index) => (
          <RoadmapItem key={index} gap={gap} />
        ))}
      </div>
    </div>
  );

  const renderCoverLetter = () => (
    <div className="animate-fade-in">
      <CoverLetterCard coverLetter={coverLetter} />
    </div>
  );

  return (
    <div className="min-h-screen bg-scifi-900 pt-8 pb-20 px-4 relative overflow-hidden">
      <BackgroundEffects />

      <div className="max-w-6xl mx-auto relative z-10">

        {/* Top Header Controls */}
        <div className="flex items-center justify-between mb-8">
          <button
            onClick={() => navigate('/')}
            className="flex items-center space-x-2 px-4 py-2 rounded-xl glass-pill text-scifi-200 hover:text-scifi-100 hover:border-scifi-600/50 transition-all font-mono text-xs"
          >
            <ArrowLeft className="w-4 h-4 text-scifi-200" />
            <span>Return to Command Center</span>
          </button>

          <h1 className="text-2xl sm:text-3xl font-heading font-bold text-scifi-100">
            Analysis Results & Verification Dashboard
          </h1>
        </div>

        {/* Tab Switcher */}
        <div className="flex space-x-2 glass-card rounded-2xl p-1.5 mb-8 overflow-x-auto border border-scifi-600/30">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center space-x-2 px-4 py-3 rounded-xl text-xs font-mono font-semibold transition-all whitespace-nowrap ${
                  isActive
                    ? 'bg-gradient-to-r from-scifi-700 to-scifi-600 text-scifi-100 shadow-purple-glow'
                    : 'text-scifi-200 hover:text-scifi-100 hover:bg-white/5'
                }`}
              >
                <Icon className={`w-4 h-4 ${isActive ? 'text-scifi-100' : 'text-scifi-200'}`} />
                <span>{tab.label}</span>
              </button>
            );
          })}
        </div>

        {/* Active Tab Component */}
        <div>
          {activeTab === 'overview' && renderOverview()}
          {activeTab === 'unified' && renderUnified()}
          {activeTab === 'ats' && renderATS()}
          {activeTab === 'rewrites' && renderRewrites()}
          {activeTab === 'roadmap' && renderRoadmap()}
          {activeTab === 'coverletter' && renderCoverLetter()}
        </div>

      </div>
    </div>
  );
};

export default Results;
